const e="mchenry-county-fair-talent-contest",c=2026,t="Built from the 2026 contest rules and entry form (2 pages). The rules print no complaints procedure, no ranks or points for places and no categories of acts. The two contacts' e-mail addresses are personal webmail and are not copied; their phone numbers are kept. The lowest age is not printed, so the template Junior band 5-14 is a placeholder; the rules say 14 years or younger. The 2025 first-place winners' ineligibility until 2027 is kept as a rule. The entry form signature lines are not copied.",n={Title:"Rules & Criteria",Subtitle:"McHenry County Fair 62nd Annual Talent Contest 2026: solo and group acts in a Junior and a Senior division, on {{ContestDate}}.",NoticeTitle:"Please Read Before Registering",Notice:"Some rules have changed for 2026. Entries must reach the fair office by {{EntryDeadline}}. Any act longer than four minutes is disqualified.",Notes:["Please read the rules carefully; some rules changed for 2026.","Rehearsal Day: {{RehearsalDay}}."],Sections:[{Key:"general",Title:"General",Items:["The contest is a judged competition. All judges are chosen from qualified people with expertise in the performing arts.","Judging decisions are final.","The contest is held on {{ContestDate}} at {{ContestVenue}}. The Junior Division begins at {{JuniorStart}}, followed by the Senior Division at {{SeniorStart}}.","Contestants should arrive at least 30 minutes before their division begins.","Performance order is chosen by a random number drawing on Rehearsal Day.","Acts must be four (4) minutes or less. Any act longer than four minutes is disqualified.","Set-up time is limited to five (5) minutes.","The timing of an act starts when the music starts, the contestant makes the first movement, or the contestant speaks to the audience. Timing stops when the act is fully completed.","The stage is 13 feet deep by 27 feet wide.","The fair provides electrical outlets, hand-held corded microphones, lighting and an electric keyboard. Please tell the talent committee about any special needs.","Each act supplies its own musical accompaniment. A sound system is available with connections for MP3 players and smartphones.","If the first-place act cannot perform at any scheduled time, the runner-up is invited to attend.","Parents, teachers and family members are encouraged to attend Rehearsal Day and the contest."]},{Key:"eligibility",Title:"Who can enter",Items:["The contest is open to any individual or group who is 21 years of age or younger and who lives in or attends school in McHenry County.","First-place winners of the 2025 contest are not eligible to compete in the same division until 2027.","Contestants who are 14 years old or younger on {{AgeCutoffDate}} compete in the Junior Division.","Contestants who are 15-21 years old on {{AgeCutoffDate}} compete in the Senior Division.","Proof of age may be required.","A group entry is placed in the division of its oldest member, and all members must meet the eligibility requirements.","A contestant may take part in only one act and one division.","An accompanist may take part in only one act per division.","All persons who have visual importance in the act must meet the eligibility requirements."]},{Key:"registration",Title:"How to enter",Items:["Fill in the Official Entry Form completely and mail it with the entry fee to {{MailingAddress}}, or enter online at {{OnlineEntry}}.","Make entry fee checks payable to the McHenry County Fair Association.","All entries must be in the fair office by {{EntryDeadline}}. The talent committee is not responsible for postal delays.","Near the deadline, entries may be dropped off at the fair office: {{FairOffice}}.","For a group entry (more than one contestant), all other members must list their names, addresses, ages and birth dates on the reverse side of the entry form.","The entry form asks for: name of contestant or group leader, street address, city, state and zip, phone number, e-mail, age and birth date of the contestant, division (Junior age 14 and under, or Senior age 15 to 21), type of act, and number of persons in the act.","The contestant or group leader signs the form to confirm that they have read and understand all the contest rules, agree to follow the rules and guidelines of the organizers, and will behave in a courteous and sportsmanlike manner.","For questions, contact {{TalentContact1}} or {{TalentContact2}}."]},{Key:"fees",Title:"Fees",Items:["The entry fee is {{EntryFee}}."]},{Key:"dates",Title:"Dates",Items:["Entries are due by {{EntryDeadline}}.","Rehearsal Day is {{RehearsalDay}}.","The contest is held on {{ContestDate}}.","The State Talent Competition is held in {{StateCompetition}}."]},{Key:"venue",Title:"Venue",Items:["The contest and Rehearsal Day are held at {{ContestVenue}}."]},{Key:"levels",Title:"Rehearsal Day and State competition",Items:["Rehearsal Day gives contestants a chance to see the stage, rehearse the act and ask questions. Qualified people help and give suggestions on how to improve and polish the act.","A short talk explains what the judges look for, with the judging categories and helpful hints. The Sound Tech Manager works with each act to make sure it sounds its best.","Attendance on Rehearsal Day is not mandatory, but it is highly recommended.","Rehearsal Day may become a mandatory Semi-Finals elimination round if the number of entries is more than the limit of 8 per division. If so, contestants are told as soon as possible after the entry deadline.","The first-place winner in each division is eligible to represent McHenry County at the State Talent Competition in {{StateCompetition}}."]},{Key:"judging",Title:"Judging",Items:["Acts are judged in six categories for a perfect score of 100 points: Entertainment Value 30, Natural Ability 30, Appearance 10, Audience Contact 10, Choice of Material 10 and Showmanship 10.","Judging decisions are final."]},{Key:"prizes",Title:"Prizes",Items:["In each division the first, second and third place winners receive {{PrizeFirst}}, {{PrizeSecond}} and {{PrizeThird}}."]}],Documents:[{Title:"2026 Contest Rules and Entry Form (PDF)",Url:"https://mchenrycountyfair.com/wp-content/uploads/2026/07/Rules2026.pdf"}]},a=[{ParticipantType:"Team",Source:"Rules 2 and Entry Form",Sections:{About:null,TimeAndFormat:null,Rules:["A group is placed in the division of its oldest member.","All other group members must list their names, addresses, ages and birth dates on the reverse side of the entry form."],Allowed:null,NotAllowed:null,Judging:null,Points:null,Notes:null},Markdown:`## Rules
- A group is placed in the division of its oldest member.
- All other group members must list their names, addresses, ages and birth dates on the reverse side of the entry form.`}],o=[],i=[{Title:"Talent Act",Source:"Rules 7, 9",Sections:{About:null,TimeAndFormat:["Acts must be four minutes or less. A longer act is disqualified. Set-up time is limited to five minutes."],Rules:["No voices, synthesized voices or vocal utterances are allowed on any pre-recorded accompaniment used by a vocal act.","In an instrumental solo, the only accompaniment allowed is a live or pre-recorded acoustical piano.","In a piano solo, no accompaniment is allowed.","When an electronic keyboard is used, the contestant must create all sounds live on stage."],Allowed:null,NotAllowed:["No taps or tap effects are allowed on a recording used by a tap dancer."],Judging:["Entertainment Value 30, Natural Ability 30, Appearance 10, Audience Contact 10, Choice of Material 10, Showmanship 10: total 100."],Points:null,Notes:null},Markdown:`## Time and format
- Acts must be four minutes or less. A longer act is disqualified. Set-up time is limited to five minutes.

## Rules
- No voices, synthesized voices or vocal utterances are allowed on any pre-recorded accompaniment used by a vocal act.
- In an instrumental solo, the only accompaniment allowed is a live or pre-recorded acoustical piano.
- In a piano solo, no accompaniment is allowed.
- When an electronic keyboard is used, the contestant must create all sounds live on stage.

## Not allowed
- No taps or tap effects are allowed on a recording used by a tap dancer.

## Judging
- Entertainment Value 30, Natural Ability 30, Appearance 10, Audience Contact 10, Choice of Material 10, Showmanship 10: total 100.`}],s=[],r=[{Key:"ContestDate",Kind:"date",Label:"Contest date",Value:"2026-08-07",Source:"Rules 4"},{Key:"AgeCutoffDate",Kind:"date",Label:"Age check date",Value:"2026-08-07",Source:"Rules 2"},{Key:"EntryDeadline",Kind:"date",Label:"Entries due in the fair office by 5 pm",Value:"2026-07-24",Source:"Rules 3 and 19"},{Key:"RehearsalDay",Kind:"date",Label:"Rehearsal Day (12:00 p.m.)",Value:"2026-08-01",Source:"Rules 13"},{Key:"JuniorStart",Kind:"time",Label:"Junior Division start",Value:"7:00 p.m.",Source:"Rules 4"},{Key:"SeniorStart",Kind:"time",Label:"Senior Division start",Value:"approximately 8:30 p.m.",Source:"Rules 4"},{Key:"StateCompetition",Kind:"text",Label:"State Talent Competition",Value:"Springfield, Illinois, in January 2027",Source:"Rules 11"},{Key:"ContestVenue",Kind:"address",Label:"Contest and rehearsal venue",Value:{Name:"Hansen Pavilion",Address:"",City:"",MapUrl:"",Directions:""},Source:"Rules 4 and 13"},{Key:"FairOffice",Kind:"address",Label:"Fair office (drop-off)",Value:{Name:"McHenry County Fair office",Address:"11900 Country Club Road",City:"Woodstock",MapUrl:"",Directions:""},Source:"Rules 3"},{Key:"MailingAddress",Kind:"address",Label:"Mail entries to",Value:{Name:"McHenry County Fair Talent Contest",Address:"P.O. Box 375",City:"Woodstock, Illinois 60098",MapUrl:"",Directions:""},Source:"Rules 19"},{Key:"OnlineEntry",Kind:"link",Label:"Online entry",Value:"www.McHenryCountyFair.com",Source:"Rules 19"},{Key:"EntryFee",Kind:"fee",Label:"Entry fee",Value:"$10.00 per act (non-refundable)",Source:"Rules 3"},{Key:"PrizeFirst",Kind:"prize",Label:"First place prize",Value:"$200",Source:"Rules 10"},{Key:"PrizeSecond",Kind:"prize",Label:"Second place prize",Value:"$150",Source:"Rules 10"},{Key:"PrizeThird",Kind:"prize",Label:"Third place prize",Value:"$100",Source:"Rules 10"},{Key:"TalentContact1",Kind:"contact",Label:"Talent contest contact",Value:{Name:"Nancy Lammers",Role:"Talent committee",Phone:"847-567-8363",WhatsApp:"",Email:""},Source:"Rules 18"},{Key:"TalentContact2",Kind:"contact",Label:"Talent contest contact",Value:{Name:"Kathy Thomas",Role:"Talent committee",Phone:"815-245-6085",WhatsApp:"",Email:""},Source:"Rules 18"},{Key:"Announcements",Kind:"news",Label:"News printed in the rules",Value:[{Date:"",Title:"Rules changed for 2026",Text:"Some rules have changed for 2026. Please read the rules carefully.",Url:""}],Source:"Rules cover"}],l=[{Claim:"Rules, eligibility, entry steps, dates, fee, prizes and judging categories are taken from the organiser's 2026 contest rules and entry form.",SourceType:"Primary - the event's own rules document",Source:"McHenry County Fair Talent Contest 2026 rules",Url:"https://mchenrycountyfair.com/wp-content/uploads/2026/07/Rules2026.pdf"}],d={TemplateKey:e,Year:2026,Note:t,Page:n,ParticipantTypes:a,AgeGroups:o,Competitions:i,CompetitionAgeGroups:s,Variables:r,Evidence:l};export{o as AgeGroups,s as CompetitionAgeGroups,i as Competitions,l as Evidence,t as Note,n as Page,a as ParticipantTypes,e as TemplateKey,r as Variables,c as Year,d as default};
